Source code in <code>src/evolzen/evaluation/rhae_scorer.py</code> <pre><code>@dataclass(frozen=True)
class RHAEResult:
    system_actions: int
    human_reference_actions: int
    solved: bool

    @property
    def score(self) -&gt; float:
        """RHAE score in [0, 1+]. 1.0 means the system matched the human reference exactly;
        &gt; 1.0 means the system was *more* action-efficient than the human reference."""
        if not self.solved or self.system_actions == 0:
            return 0.0
        return self.human_reference_actions / self.system_actions
